#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef vector<ll> vll;

const int mod = 998244353;

// NTT primes and primitive roots
const int NTTPrimes[] = {1053818881, 1051721729, 1045430273, 1012924417, 1007681537, 1004535809, 998244353, 985661441, 976224257, 975175681};
const int NTTPrimitiveRoots[] = {7, 6, 3, 5, 3, 3, 3, 3, 3, 17};

// fast I/O
int readInt() {
    int x = 0, sign = 1;
    char c = getchar();
    while (!(c >= '0' && c <= '9') && c != '-') c = getchar();
    if (c == '-') { sign = -1; c = getchar(); }
    while (c >= '0' && c <= '9') {
        x = x * 10 + (c - '0');
        c = getchar();
    }
    return sign * x;
}

vll readInts(int n) {
    vll a(n);
    for (int i = 0; i < n; ++i) a[i] = readInt();
    return a;
}

// modular exponentiation
ll modPow(ll a, ll n, ll p) {
    ll res = 1;
    while (n) {
        if (n & 1) res = res * a % p;
        a = a * a % p;
        n >>= 1;
    }
    return res;
}

// modular inverse
ll modInv(ll a, ll p) {
    ll b = p, x0 = 1, x1 = 0;
    while (b) {
        ll q = a / b;
        ll t = a % b; a = b; b = t;
        t = x0 - q * x1; x0 = x1; x1 = t;
    }
    return x0 < 0 ? x0 + p : x0;
}

// Garner preprocessing and batch
vll garnerPrepare(const vector<int>& m) {
    int n = m.size();
    vll gamma(n, 0);
    for (int k = 1; k < n; ++k) {
        ll prod = 1;
        for (int i = 0; i < k; ++i) prod = prod * m[i] % m[k];
        gamma[k] = modInv(prod, m[k]);
    }
    return gamma;
}

vll garnerBatch(const vector<int>& u, const vector<int>& m, const vll& gamma) {
    int n = u.size();
    vll v(n);
    v[0] = u[0];
    for (int k = 1; k < n; ++k) {
        ll temp = v[k-1];
        for (int j = k-2; j >= 0; --j) temp = (temp * m[j] + v[j]) % m[k];
        v[k] = (u[k] - temp) * gamma[k] % m[k];
        if (v[k] < 0) v[k] += m[k];
    }
    return v;
}

// Shoup's reduction helper (same as modh in Java)
ll modh(ll a, ll M, int h, int p) {
    ll r = a - ((M * (a & ((1LL<<31)-1)) >> 31) + M * (a >> 31) >> (h-31)) * p;
    return r < p ? r : r - p;
}

// NTT implementation (Montgomery + Barrett version)
vll nttmb(const vll& src, int n, bool inverse, int P, int g) {
    vll dst = src;
    dst.resize(n);

    int h = __builtin_ctz(n);
    ll K = (ll)(1 << (31 - __builtin_clz(P)));
    if ((K<<1) >= (1LL<<32)) K = 1LL<<31;
    else K <<= 1;
    int H = __builtin_ctzll(K) * 2;
    ll M = K * K / P;

    vll wws(1 << (h-1));
    ll dw = inverse ? modPow(g, P-1 - (P-1)/n, P) : modPow(g, (P-1)/n, P);
    ll w = (1LL<<32) % P;
    for (int k = 0; k < (1 << (h-1)); ++k) {
        wws[k] = w;
        w = modh(w * dw, M, H, P);
    }

    ll J = modInv(P, 1LL<<32);
    for (int i = 0; i < h; ++i) {
        int step = 1 << (h-1-i);
        for (int j = 0; j < (1 << i); ++j) {
            int offset = j << (h-i);
            for (int k = 0; k < step; ++k) {
                int s = offset + k;
                int t = s + step;
                ll u = (dst[s] - dst[t] + 2*P) * wws[k];
                dst[s] = dst[s] + dst[t];
                if (dst[s] >= 2*P) dst[s] -= 2*P;
                ll Q = (ll)((unsigned ll)(u<<32) * (unsigned ll)J >> 32);
                dst[t] = (u >> 32) - (Q * P >> 32) + P;
            }
        }
        if (i < h-1) {
            for (int k = 0; k < (1 << (h-2-i)); ++k) {
                wws[k] = wws[k*2];
            }
        }
    }
    for (int i = 0; i < n; ++i) {
        if (dst[i] >= P) dst[i] -= P;
    }
    // bit-reverse permutation
    for (int i = 0, j = 0; i < n; ++i) {
        if (i < j) swap(dst[i], dst[j]);
        int t = n >> 1;
        while (j & t) {
            j ^= t;
            t >>= 1;
        }
        j ^= t;
    }
    if (inverse) {
        ll invN = modInv(n, P);
        for (int i = 0; i < n; ++i) dst[i] = modh(dst[i] * invN, M, H, P);
    }
    return dst;
}

// Single NTT convolution (no Chinese remainder)
vll convoluteSimply(const vll& a, const vll& b, int P, int g) {
    int m = max(2, (1 << (32 - __builtin_clz(max((int)a.size(), (int)b.size()) - 1))) << 2);
    vll fa = nttmb(a, m, false, P, g);
    vll fb = (&a == &b) ? fa : nttmb(b, m, false, P, g);
    for (int i = 0; i < m; ++i) fa[i] = fa[i] * fb[i] % P;
    return nttmb(fa, m, true, P, g);
}

// Multi-prime convolution with Garner
vll convolute(const vll& a, const vll& b) {
    const int USE = 2;
    int m = max(2, (1 << (32 - __builtin_clz(max((int)a.size(), (int)b.size()) - 1))) << 2);
    vll fs[USE];
    vector<int> mods(USE);
    for (int k = 0; k < USE; ++k) {
        int P = NTTPrimes[k], g = NTTPrimitiveRoots[k];
        vll fa = nttmb(a, m, false, P, g);
        vll fb = (&a == &b) ? fa : nttmb(b, m, false, P, g);
        for (int i = 0; i < m; ++i) fa[i] = fa[i] * fb[i] % P;
        fs[k] = nttmb(fa, m, true, P, g);
        mods[k] = P;
    }

    vll gamma = garnerPrepare(mods);
    vector<int> buf(USE);
    for (int i = 0; i < (int)fs[0].size(); ++i) {
        for (int j = 0; j < USE; ++j) buf[j] = (int)fs[j][i];
        vll res = garnerBatch(buf, mods, gamma);
        ll ret = 0;
        for (int j = (int)res.size()-1; j >= 0; --j) ret = ret * mods[j] + res[j];
        fs[0][i] = ret;
    }
    return fs[0];
}

// Multiply polynomials naively
vll mulnaive(const vll& a, const vll& b) {
    vll c(a.size() + b.size() - 1, 0);
    ll big = 8LL * mod * mod;
    for (int i = 0; i < (int)a.size(); ++i) {
        for (int j = 0; j < (int)b.size(); ++j) {
            c[i+j] += a[i] * b[j];
            if (c[i+j] >= big) c[i+j] -= big;
        }
    }
    for (int i = 0; i < (int)c.size(); ++i) c[i] %= mod;
    return c;
}

// Remove trailing zeros
vll clean(const vll& a) {
    int i = (int)a.size() - 1;
    while (i >= 0 && a[i] == 0) --i;
    if (i < 0) return vll();
    if (i == (int)a.size() - 1) return a;
    return vll(a.begin(), a.begin() + i + 1);
}

void solve() {
    int n = readInt();
    int K = readInt();
    vll d = readInts(K);
    vll f(20, 0);
    for (int i = 0; i < K; ++i) {
        for (int j = 0; j < K; ++j) {
            f[10 + d[i] - d[j]]++;
        }
    }
    n /= 2;
    vll g = {1};
    for (int D = 17; D >= 0; --D) {
        g = clean(convoluteSimply(g, g, mod, 3));
        if (n & (1 << D)) {
            g = clean(mulnaive(g, f));
        }
    }
    ll ans = (ll)n * 10 < (ll)g.size() ? g[(ll)n * 10] : 0;
    printf("%lld\n", ans);
}

int main() {
    solve();
    return 0;
